pub struct Solution;

impl Solution {
    pub fn solve_n_queens(n: i32) -> Vec<Vec<String>> {
        let n = n as usize;
        let mut results = Vec::new();
        let mut queens = vec![0; n];

        Self::backtrack(0, n, 0, 0, 0, &mut queens, &mut results);

        results
    }

    fn backtrack(
        row: usize,
        n: usize,
        cols: u32,
        diag1: u32,
        diag2: u32,
        queens: &mut Vec<usize>,
        results: &mut Vec<Vec<String>>,
    ) {
        if row == n {
            let mut board = Vec::with_capacity(n);
            for &col in queens.iter() {
                let mut row_str = vec![b'.'; n];
                row_str[col] = b'Q';
                board.push(String::from_utf8(row_str).unwrap());
            }
            results.push(board);
            return;
        }

        for col in 0..n {
            let d1 = row + col;
            let d2 = row + n - 1 - col;
            if (cols & (1 << col)) == 0 && (diag1 & (1 << d1)) == 0 && (diag2 & (1 << d2)) == 0 {
                queens[row] = col;
                Self::backtrack(
                    row + 1,
                    n,
                    cols | (1 << col),
                    diag1 | (1 << d1),
                    diag2 | (1 << d2),
                    queens,
                    results,
                );
            }
        }
    }
}

